from lib import *
S = SS('f15')
R = J('f15'); e = R['err']; rl_ = R['reload']
steps = [
    step("debug 的几种设置方式效果相同:默认 app.debug = False、config[DEBUG] = False、logger 级别 0(NOTSET)、jinja auto_reload = False;FLASK_DEBUG=1、app.config['DEBUG'] = True、app.debug = True 三种方式都得到 app.debug = True、logger 级别 10(DEBUG)、jinja auto_reload = True;FLASK_DEBUG=0 与默认相同。TEMPLATES_AUTO_RELOAD 在这些情况下始终是 None(由 debug 决定)。", t=tl(S(1)), done=lidx(S(1), '默认  ', 'FLASK_DEBUG=0'), mark=lidx(S(1), 'FLASK_DEBUG=1', 'app.config["DEBUG"]=True', 'app.debug = True'), kv=KV([['debug 为 True 时', 'logger 级别 10、模板自动重载'], ['TEMPLATES_AUTO_RELOAD', '始终 None(跟随 debug)']], ['debug 为 True 时'])),
    step(f"出错时的响应:/boom 里 1 / 0。debug=False 得到 500,正文只有 {e['debug=False']['size']} 字节,没有 Traceback、没有源码;debug=True 得到 500,正文 {e['debug=True']['size']} 字节,含完整 Traceback、调试器标记、能看到源码行 return 1 / 0。调试器页面把应用的源码与局部变量暴露给任何能访问这个地址的人。", t=tl(S(2)), done=lidx(S(2), 'debug=False', 'debug=True'), kv=KV([['debug=False', f"500,{e['debug=False']['size']} 字节,无 traceback"], ['debug=True', f"500,{e['debug=True']['size']} 字节,含 traceback 与源码"]], ['debug=True'])),
    step("调试器的控制台靠 PIN 解锁(这里用环境变量 WERKZEUG_DEBUG_PIN 固定实验 PIN,只在本机实验服务器上验证):页面内嵌了 SECRET 与 EVALEX = true、共 7 个栈帧;① 没有 PIN 认证就请求在栈帧里执行代码 → 返回的只是应用自己的 500 页(含 ZeroDivisionError),没有执行结果;② 错误 PIN → {\"auth\": false, \"exhausted\": false};③ 正确 PIN → {\"auth\": true …} 并设置 __wzdb… cookie;④ 带这个 cookie 再执行 __import__(\"os\").getpid() → 返回里是服务器进程的 pid;⑤ 调试器的静态资源(style.css)不需要 PIN。认证之后任何请求都能在服务器上执行任意代码,所以绝不能把 debug 开着暴露到公网。", t=tl(S(3)), mark=lidx(S(3), '①', '②', '③', '④'), done=lidx(S(3), '⑤', 'EVALEX'), kv=KV([['无 PIN', '不执行代码'], ['错误 PIN', 'auth: false'], ['正确 PIN + cookie', '能执行代码(返回服务器 pid)']], ['正确 PIN + cookie'])),
    step(f"模板自动重载:非 debug 的服务器上,第一次读到 'version 1',改了模板文件后仍读到 {rl_['非 debug'][1]!r};带 --debug 的服务器改文件后立刻读到 {rl_['--debug'][1]!r}(同样没有启用文件重载器,是 jinja 的 auto_reload 在起作用)。", t=tl(S(4)), done=lidx(S(4), '非 debug', '--debug'), kv=KV([['非 debug', '改模板后仍是 version 1'], ['--debug', '改模板后立刻是 version 2']], ['--debug'])),
    step("--debug 与重载器是两件事:flask run --debug --no-reload 日志里只有「Debug mode: on」「Running on …」「Press CTRL+C to quit」,没有「Restarting with stat」(没有重载器进程),但 debug 页与模板自动重载仍然生效。", t=tl(S(5)), done=lidx(S(5), 'Debug mode: on'), kv=KV([['--debug --no-reload', '调试器与 DEBUG 开着,不监视代码文件']], ['--debug --no-reload'])),
]
A = mkartf('f15', 15, 'Flask,Debug,调试器,自动重载,真实验证,动画演示',
    f'验证 Flask debug 模式:FLASK_DEBUG、config、app.debug 等价,debug 时 logger=DEBUG、模板自动重载;出错页从 {e["debug=False"]["size"]} 字节变成 {e["debug=True"]["size"]} 字节含 traceback 与源码;调试器控制台要 PIN,通过 PIN 后能在服务器上执行代码;--no-reload 只关重载器。',
    'debug=True 到底开启了什么?它的错误页暴露了什么?调试器控制台是怎么被 PIN 保护的?模板改了为什么不用重启?这篇用真实的开发服务器一项项验证。',
    [(f'{e["debug=False"]["size"]} → {e["debug=True"]["size"]}', '同一个 500 错误页的正文字节数(debug 关 → 开)'), ('PIN', '调试器控制台执行代码需要的认证'), ('3 种', '等价的 debug 设置方式(FLASK_DEBUG、config、app.debug)')],
    [('debug 的设置方式', '<p>上一篇:<a href="flask-flask-and-werkzeug.html">Flask 与 Werkzeug 的关系</a>;自动重载进程的细节见<a href="flask-app-run.html">app.run() 的启动过程</a>;安全风险的专题见<a href="flask-debugger-risk.html">开发模式 Debugger 风险</a>。</p>'), ('出错页的差别', None), ('调试器控制台与 PIN', None), ('模板自动重载', None), ('--debug 与 --no-reload', None)],
    steps, [ENV_F + '。调试器实验只在本机自己起的服务器(127.0.0.1)上进行,PIN 用 WERKZEUG_DEBUG_PIN 环境变量固定为实验值', '没有验证:PIN 的生成算法(machine-id、MAC 地址、用户名等)与能否被推算(见第 132 篇)、Docker 容器里的 PIN、debug 页面在反向代理后的表现、exception 页面在 PROPAGATE_EXCEPTIONS 单独设置时的行为'], 'debug 模式')
